        <span class="kpi-badge badge-red">⚡ Peak Stress</span>
      </div>
      <div class="kpi-card" style="--kpi-color:#059669">
        <div class="kpi-label">Renewable Energy Ratio</div>
        <div class="kpi-value">35.4<span style="font-size:16px;font-weight:500">%</span></div>
        <div class="kpi-sub">Off-Peak: 39.3% · Peak: 29.0%</div>
        <span class="kpi-badge badge-green">↑ Off-Peak Advantage</span>
      </div>
      <div class="kpi-card" style="--kpi-color:#d97706">
        <div class="kpi-label">Mean Optimization Reward</div>
        <div class="kpi-value">−11.8</div>
