        <span class="kpi-badge badge-red">Below Target</span>
      </div>
      <div class="kpi-card" style="--kpi-color:#7c3aed">
        <div class="kpi-label">Avg Queue Length</div>
        <div class="kpi-value">4.6<span style="font-size:16px;font-weight:500"> veh</span></div>
        <div class="kpi-sub">Highway: 4.61 · Urban: 4.57</div>
        <span class="kpi-badge badge-yellow">Consistent</span>
      </div>
      <div class="kpi-card" style="--kpi-color:#0ea5e9">
        <div class="kpi-label">Avg Charging Duration</div>
        <div class="kpi-value">178.7<span style="font-size:16px;font-weight:500"> min</span></div>
